WITH filtered AS (SELECT id, customer_id, account_type, balance, status, CONCAT(account_type, '/', status) AS account_type_status FROM accounts WHERE customer_id IS NOT NULL AND balance IS NULL) SELECT s.*, latest.merchant, latest.txn_time FROM filtered s JOIN LATERAL (SELECT c.merchant, c.txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE
